+func (c *TestWindowsMDMClient) shouldAuth(req *fleet.SyncML) (bool, *string) {
+	for _, cmd := range req.GetOrderedCmds() {
+		if cmd.Verb == fleet.CmdStatus && cmd.Cmd.Chal != nil {
